# --------------------------------------------------------------------------
def topological_order(nodes, edges):
    """Kahn's algorithm; ties broken by band then declaration order (stable)."""
    order_hint = {n["id"]: i for i, n in enumerate(nodes)}
    parents = {n["id"]: set() for n in nodes}
    children = {n["id"]: set() for n in nodes}
    for src, dst, *_ in edges:
        parents[dst].add(src)
        children[src].add(dst)

    remaining = dict((k, set(v)) for k, v in parents.items())
    out = []
    while remaining:
        ready = sorted([k for k, v in remaining.items() if not v], key=lambda k: order_hint[k])
        if not ready:
            raise ValueError(f"cycle detected among {sorted(remaining)}")
        for k in ready:
            out.append(k)
            del remaining[k]
        for v in remaining.values():
            v.difference_update(ready)
    return out


def spearman(df, a, b):
    """Pairwise-complete Spearman, on log1p for the heavy-tailed dollar columns."""
    heavy = {"Lump Sum", "Non-Economic Loss", "Future Economic Loss", "Claimant Weekly Income"}
    s = df[[a, b]].dropna().copy()
    if len(s) < 30:
        return None, len(s)
    for name in (a, b):
        if name in heavy:
            s[name] = np.log1p(s[name])
    if s[a].nunique() < 2 or s[b].nunique() < 2:
        return None, len(s)
    return float(stats.spearmanr(s[a], s[b]).statistic), len(s)


def main():
    df = pd.read_csv(CSV)
    # numeric codes for the two string columns so associations are computable
    num = df.copy()
    num["Claimant Gender"] = (num["Claimant Gender"] == "Male").astype(int)
    num["Nature"] = (num["Nature"] == "Damages").astype(int)

    order = topological_order(NODES, EDGES)
    rank = {n: i for i, n in enumerate(order)}
    for src, dst, *_ in EDGES:
        assert rank[src] < rank[dst], f"back-edge {src} -> {dst}"

    csv_order = list(df.columns)
    csv_rank = {c: i for i, c in enumerate(csv_order)}
    violations = [(s, d) for s, d, *_ in EDGES if csv_rank[d] < csv_rank[s]]

    edges_out = []
    for src, dst, sign, strength, mech in EDGES:
        rho, n = spearman(num, src, dst)
        # An asserted direct effect whose *marginal* association points the other way.
        # Not an error: it is confounding, and it is the reason the generator needs the
        # graph rather than the correlation matrix.
        confounded = (
            rho is not None and abs(rho) > 0.03
            and ((sign == "+" and rho < 0) or (sign == "-" and rho > 0))
        )
        edges_out.append(dict(
            source=src, target=dst, sign=sign, strength=strength, mechanism=mech,
            rho=None if rho is None else round(rho, 3), n=n,
            sign_conflicts_marginal=confounded,
            csv_order_violation=csv_rank[dst] < csv_rank[src],
        ))

    missing_out = []
    for src, dst, sign, mech in MISSING_EDGES:
        missing_out.append(dict(source=src, target=dst, sign=sign, mechanism=mech))

    parents = {n["id"]: [] for n in NODES}
    for e in edges_out:
        parents[e["target"]].append(e["source"])

    # collider evidence for Lump Sum
    m = df.dropna(subset=["Non-Economic Loss", "Future Economic Loss"])
    a = np.log1p(m["Non-Economic Loss"]).to_numpy()
    b = np.log1p(m["Future Economic Loss"]).to_numpy()
    c = np.log(m["Lump Sum"]).to_numpy()

    def resid(v, z):
        X = np.column_stack([np.ones(len(z)), z])
        return v - X @ np.linalg.lstsq(X, v, rcond=None)[0]

    collider = dict(
        pair=["Non-Economic Loss", "Future Economic Loss"],
        collider="Lump Sum",
        n=int(len(m)),
        rho_marginal=round(float(stats.spearmanr(a, b).statistic), 3),
        rho_given_collider=round(float(stats.spearmanr(resid(a, c), resid(b, c)).statistic), 3),
    )

    doc = dict(
        name="nsw-ctp-severity",
        version="1.0",
        target="Lump Sum",
        n_rows=int(len(df)),
        description=(
            "DAG for NSW CTP impairment lump-sum awards, for DAG-aware autoregressive "
            "generation with TabPFN (Tugnoli et al., 2026). UNREVIEWED: edges, signs and "
            "mechanisms were generated by a large language model from NSW CTP scheme "
            "mechanics and claim chronology; no domain expert has reviewed them. The rho "
            "annotations are descriptive and do not validate any edge."
        ),
        provenance=dict(
            edge_source="llm_generated",
            model="Claude (Anthropic)",
            domain_review="none",
            reviewed_by=None,
            reviewed_at=None,
            basis="Motor Accident Injuries Act 2017 / Motor Accidents Compensation Act 1999 "
                  "heads of damage, as represented in the model's training data. No section-level "
                  "citations were recorded.",
            caveat="Treat every edge as a hypothesis pending review by a NSW CTP practitioner. "
                   "Descriptive statistics in the note/mechanism strings are verified by "
                   "causal/verify_claims.py; the causal assertions are not verifiable from this data.",
        ),
        bands=BANDS,
        nodes=NODES,
        edges=edges_out,
        parents=parents,
        topological_order=order,
        csv_column_order=csv_order,
        csv_order_violations=[list(v) for v in violations],
        missingness=dict(nodes=MISSING_NODES, edges=missing_out),
        colliders=[collider],
        categorical_contrasts={"Claimant Gender": "Male vs Female",
                               "Nature": "Damages vs Settlement Approval"},
        stats=dict(
            n_nodes=len(NODES), n_edges=len(EDGES),
            n_violations=len(violations),
            n_sign_conflicts=sum(e["sign_conflicts_marginal"] for e in edges_out),
            missing_rates={c: round(float(df[c].isna().mean()), 4)
                           for c in df.columns if df[c].isna().any()},
        ),
    )
    OUT.write_text(json.dumps(doc, indent=2), encoding="utf-8")

    print(f"wrote {OUT}")
    print(f"nodes={len(NODES)} edges={len(EDGES)} "
          f"csv-order violations={len(violations)}/{len(EDGES)}")
    print("topological order:")
    for i, nid in enumerate(order):
        print(f"  {i:2d}. {nid}")
    print(f"collider check: rho(NEL,FEL)={collider['rho_marginal']} -> "
          f"{collider['rho_given_collider']} given Lump Sum")


if __name__ == "__main__":
    main()
